CREATE TABLE IF NOT EXISTS ft_company_daily_price(entity_id INTEGER NOT NULL REFERENCES dm_company(id),trading_date TEXT NOT NULL,open REAL,high REAL,low REAL,close REAL NOT NULL,adjusted_close REAL,volume REAL,source TEXT NOT NULL,retrieved TEXT NOT NULL,PRIMARY KEY(entity_id,trading_date,source)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS ft_index_daily_price(entity_id INTEGER NOT NULL REFERENCES dm_index(id),trading_date TEXT NOT NULL,open REAL,high REAL,low REAL,close REAL NOT NULL,adjusted_close REAL,volume REAL,source TEXT NOT NULL,retrieved TEXT NOT NULL,PRIMARY KEY(entity_id,trading_date,source)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS misc_market_data_queue(kind TEXT NOT NULL,entity_id INTEGER NOT NULL,status TEXT,next_retry TEXT,payload_id INTEGER,last_attempt TEXT,PRIMARY KEY(kind,entity_id)) WITHOUT ROWID;
CREATE VIEW IF NOT EXISTS vw_company_daily_prices AS SELECT p.*,c.symbol,c.id company_id FROM ft_company_daily_price p JOIN dm_company c ON c.id=p.entity_id;
CREATE VIEW IF NOT EXISTS vw_index_daily_prices AS SELECT p.*,i.code,i.name,i.category FROM ft_index_daily_price p JOIN dm_index i ON i.id=p.entity_id;
CREATE VIEW IF NOT EXISTS vw_market_data_coverage AS SELECT 'COMPANY' kind,c.id entity_id,c.symbol code,p.source,min(p.trading_date) first_date,max(p.trading_date) last_date,count(p.trading_date) sessions,count(p.volume) volume_sessions FROM dm_company c LEFT JOIN ft_company_daily_price p ON p.entity_id=c.id WHERE c.active=1 OR c.id IN (SELECT company_id FROM vw_index_constituents) GROUP BY c.id,p.source UNION ALL SELECT 'INDEX',i.id,i.code,p.source,min(p.trading_date),max(p.trading_date),count(p.trading_date),count(p.volume) FROM dm_index i LEFT JOIN ft_index_daily_price p ON p.entity_id=i.id GROUP BY i.id,p.source;
CREATE VIEW IF NOT EXISTS vw_market_acquisition_progress AS SELECT * FROM misc_market_data_queue;
CREATE VIEW IF NOT EXISTS vw_company_market_performance AS WITH x AS (SELECT *, LAG(close) OVER w previous_close,LAG(volume) OVER w previous_volume,AVG(volume) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 20 PRECEDING AND 1 PRECEDING) avg_prior_volume,COUNT(volume) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 20 PRECEDING AND 1 PRECEDING) prior_volume_count,LAG(close,5) OVER w close_5,LAG(close,21) OVER w close_21,LAG(close,63) OVER w close_63,LAG(close,126) OVER w close_126,LAG(close,252) OVER w close_252,CASE WHEN COUNT(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW)=20 THEN AVG(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) END ma20,CASE WHEN COUNT(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 49 PRECEDING AND CURRENT ROW)=50 THEN AVG(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 49 PRECEDING AND CURRENT ROW) END ma50,CASE WHEN COUNT(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 99 PRECEDING AND CURRENT ROW)=100 THEN AVG(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 99 PRECEDING AND CURRENT ROW) END ma100,CASE WHEN COUNT(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 199 PRECEDING AND CURRENT ROW)=200 THEN AVG(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 199 PRECEDING AND CURRENT ROW) END ma200 FROM vw_company_daily_prices WINDOW w AS (PARTITION BY entity_id,source ORDER BY trading_date)) SELECT *,close-previous_close price_change,100.0*(close/previous_close-1) daily_return_pct,100.0*(volume/NULLIF(previous_volume,0)-1) volume_change_pct,CASE WHEN prior_volume_count=20 THEN volume/NULLIF(avg_prior_volume,0) END relative_volume,100.0*(close/close_5-1) return_5d_pct, 100.0*(close/close_21-1) return_21d_pct, 100.0*(close/close_63-1) return_63d_pct, 100.0*(close/close_126-1) return_126d_pct, 100.0*(close/close_252-1) return_252d_pct FROM x;
CREATE VIEW IF NOT EXISTS vw_index_market_performance AS WITH x AS (SELECT *, LAG(close) OVER w previous_close,LAG(volume) OVER w previous_volume,AVG(volume) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 20 PRECEDING AND 1 PRECEDING) avg_prior_volume,COUNT(volume) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 20 PRECEDING AND 1 PRECEDING) prior_volume_count,LAG(close,5) OVER w close_5,LAG(close,21) OVER w close_21,LAG(close,63) OVER w close_63,LAG(close,126) OVER w close_126,LAG(close,252) OVER w close_252,CASE WHEN COUNT(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW)=20 THEN AVG(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) END ma20,CASE WHEN COUNT(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 49 PRECEDING AND CURRENT ROW)=50 THEN AVG(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 49 PRECEDING AND CURRENT ROW) END ma50,CASE WHEN COUNT(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 99 PRECEDING AND CURRENT ROW)=100 THEN AVG(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 99 PRECEDING AND CURRENT ROW) END ma100,CASE WHEN COUNT(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 199 PRECEDING AND CURRENT ROW)=200 THEN AVG(close) OVER (PARTITION BY entity_id,source ORDER BY trading_date ROWS BETWEEN 199 PRECEDING AND CURRENT ROW) END ma200 FROM vw_index_daily_prices WINDOW w AS (PARTITION BY entity_id,source ORDER BY trading_date)) SELECT *,close-previous_close price_change,100.0*(close/previous_close-1) daily_return_pct,100.0*(volume/NULLIF(previous_volume,0)-1) volume_change_pct,CASE WHEN prior_volume_count=20 THEN volume/NULLIF(avg_prior_volume,0) END relative_volume,100.0*(close/close_5-1) return_5d_pct, 100.0*(close/close_21-1) return_21d_pct, 100.0*(close/close_63-1) return_63d_pct, 100.0*(close/close_126-1) return_126d_pct, 100.0*(close/close_252-1) return_252d_pct FROM x;
CREATE VIEW IF NOT EXISTS vw_company_daily_volume AS SELECT * FROM vw_company_market_performance;
CREATE VIEW IF NOT EXISTS vw_sector_daily_performance AS SELECT * FROM vw_index_market_performance WHERE category='SECTOR';
CREATE VIEW IF NOT EXISTS vw_factor_daily_performance AS SELECT * FROM vw_index_market_performance WHERE category='FACTOR';
CREATE INDEX IF NOT EXISTS ix_market_snapshot_company ON dm_snapshot(company_id,status,id);
CREATE VIEW IF NOT EXISTS vw_index_constituent_daily_performance AS SELECT m.index_id,m.index_name,m.category,p.trading_date,count(DISTINCT p.entity_id) valid_companies,(SELECT count(*) FROM vw_index_constituents z WHERE z.index_id=m.index_id) eligible_companies,avg(p.daily_return_pct) equal_weight_daily_return_pct,avg(p.return_21d_pct) mean_constituent_21d_return_pct,avg(p.relative_volume) mean_relative_volume,sum(CASE WHEN p.daily_return_pct>0 THEN 1 ELSE 0 END) advancing,sum(CASE WHEN p.daily_return_pct<0 THEN 1 ELSE 0 END) declining,'CURRENT_MEMBERSHIP_RETROSPECTIVE' methodology FROM vw_index_constituents m JOIN vw_company_market_performance p ON p.entity_id=m.company_id GROUP BY m.index_id,p.trading_date;
CREATE VIEW IF NOT EXISTS vw_sector_breadth AS SELECT * FROM vw_index_constituent_daily_performance WHERE category='SECTOR';
CREATE VIEW IF NOT EXISTS vw_factor_breadth AS SELECT * FROM vw_index_constituent_daily_performance WHERE category='FACTOR';
CREATE VIEW IF NOT EXISTS vw_company_relative_strength AS SELECT c.entity_id,c.symbol,c.trading_date,c.source,b.source benchmark_source,100.0*((1+c.return_21d_pct/100.0)/NULLIF(1+b.return_21d_pct/100.0,0)-1) relative_21d_pct,100.0*((1+c.return_63d_pct/100.0)/NULLIF(1+b.return_63d_pct/100.0,0)-1) relative_63d_pct FROM vw_company_market_performance c JOIN vw_index_market_performance b ON b.trading_date=c.trading_date AND b.code='NIFTY_500';
